import csv
import json
import os

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
CSV_PATH = os.path.join(BASE_DIR, 'data.csv')
SUMMARY_PATH = os.path.join(BASE_DIR, 'summary.json')


def to_number(cell):
    try:
        return float(cell.strip())
    except (AttributeError, ValueError):
        return None


def read_values(path):
    with open(path, newline='', encoding='utf-8') as f:
        rows = [row for row in csv.reader(f) if any(cell.strip() for cell in row)]
    if not rows:
        return []
    if any(to_number(cell) is None for cell in rows[0]):
        rows = rows[1:]
    values = []
    for row in rows:
        numbers = [n for n in (to_number(cell) for cell in row) if n is not None]
        if numbers:
            values.append(numbers[0])
    return values


def build_summary(values):
    rows = len(values)
    if rows == 0:
        return {'rows': 0, 'average': None}
    average = sum(values) / rows
    if average.is_integer():
        average = int(average)
    return {'rows': rows, 'average': average}


def main():
    summary = build_summary(read_values(CSV_PATH))
    with open(SUMMARY_PATH, 'w', encoding='utf-8') as f:
        json.dump(summary, f, indent=2)
        f.write('\n')
    print(json.dumps(summary))


if __name__ == '__main__':
    main()

